"""Eighty-eight finite, original English contexts across all eleven skills.

Public SAT task categories inform format only. No official passage or item is
reconstructed. Families expose reuse; intended demands are not calibration.
"""
from english_common import make_item


def bp(skill, method, formula, structure, misconceptions):
    return dict(skill=skill, method=method, formula=formula, structure=structure,
                misconceptions=misconceptions, variants=4)


