DEMANDS = {
'central-ideas': ['retain both sides of a qualified account', 'match the scope or sequence requested by the stem'],
'textual-evidence': ['identify a discriminating evidence relationship', 'avoid substituting compatible details for the required contrast or prediction'],
'quantitative-evidence': ['apply the stated comparison rule to labeled values', 'distinguish group measures from unsupported individual or universal claims'],
'inferences': ['combine explicit constraints without introducing extra assumptions', 'preserve limits of the observed or represented subset'],
'words-context': ['use the contextual relationship and degree', 'reject a familiar but contextually unsupported meaning'],
'text-purpose': ['connect a local device to the surrounding argument', 'distinguish illustration or qualification from proof or total rejection'],
'cross-text': ['compare definitions or proposed tests across passages', 'preserve the difference between observed results and unresolved explanations'],
'synthesis': ['select notes that serve the specified audience and goal', 'retain changed and unchanged dimensions or a definition’s proper scope'],
'transitions': ['identify the relationship between immediately relevant propositions', 'avoid importing an unstated causal or adversarial connection'],
'boundaries': ['identify required grammatical connections before punctuating', 'distinguish coordinated predicates or integrated quotations from complete independent clauses'],
'form-structure': ['locate the actual subject or past reference event', 'choose a finite form with the required agreement and time reference'],
}


def make(family, seed):
    item = dict(CASES[family][seed % 4])
    skill = BLUEPRINTS[family]['skill']
    item['stem'] = item['stem'] or STEMS[skill]
    return make_item(family=family, seed=seed, blueprint=BLUEPRINTS[family],
                     demands=DEMANDS[skill], **item)
